# ============================================================
# 8. FIND DEPLOYMENT DEFINITIONS
# ============================================================

def discover_deployment_definitions(files):
    print_section("DEPLOYMENT DEFINITION DISCOVERY")

    job_candidates = []
    pipeline_candidates = []
    permission_candidates = []

    for file in files:
        path = file["path"]
        name = file["name"].lower()

        # Only deployment resources are allowed
        if (
            "/resources/" not in path.lower()
            and "/jobs/" not in path.lower()
            and "/pipelines/" not in path.lower()
        ):
            continue

        if name in (
            "jobs.yml",
            "jobs.yaml",
        "jobs.json"
        ):
            job_candidates.append(file)

        elif name in (
            "pipelines.yml",
            "pipelines.yaml",
            "pipeline.json",
            "pipelines.json"
        ):
            pipeline_candidates.append(file)

        elif name in (
            "permissions.yml",
            "permissions.yaml",
            "permissions.json"
        ):
            permission_candidates.append(file)

    print("\nJob deployment definitions:")
    for item in job_candidates:
        print(f"  {item['path']}")

    print("\nPipeline deployment definitions:")
    for item in pipeline_candidates:
        print(f"  {item['path']}")

    print("\nPermission definitions:")
    for item in permission_candidates:
        print(f"  {item['path']}")

    return (
        job_candidates,
        pipeline_candidates,
        permission_candidates
    )

# ============================================================
# 8A. DATABASE ARTIFACT DISCOVERY
# ============================================================

def discover_database_artifacts(files):

    print_section(
        "DATABASE ARTIFACT DISCOVERY"
    )

    catalog_files = []
    schema_files = []
    table_files = []

    for file in files:

        name = file["name"].lower()

        if name == "create_catalog.sql":

            catalog_files.append(file)

        elif name.endswith("_schema.sql"):

            schema_files.append(file)

        elif name.endswith("_tables.sql"):

            table_files.append(file)

    print("\nCatalog Files:")

    for item in catalog_files:
        print(item["path"])

    print("\nSchema Files:")

    for item in schema_files:
        print(item["path"])

    print("\nTable Files:")

    for item in table_files:
        print(item["path"])

    return (
        catalog_files,
        schema_files,
        table_files
    )

