def validate_package(files):

    print_section("PACKAGE VALIDATION")

    filenames = {
        item["name"].lower()
        for item in files
    }

    if "databricks.yml" in filenames:
        print("✓ databricks.yml found")
    else:
        print(
            "WARNING: databricks.yml not found. "
            "Continuing because the SDK deployment "
            "does not require the CLI bundle command."
        )

    optional_files = [
        "manifest.json",
        "readme.md",
        "requirements.txt"
    ]

    print("\nOptional package files:")

    for filename in optional_files:
        if filename in filenames:
            print(f"  ✓ {filename}")
        else:
            print(f"  - {filename}")

    print(
        f"\nTotal package files: {len(files)}"
    )

    return True


