# ============================================================
# 11. JOB DEFINITION NORMALIZATION
# ============================================================

def normalize_job_definition(data):

    if data is None:
        raise ValueError(
            "Empty job definition."
        )

    # {"job": {...}}
    if (
        isinstance(data, dict)
        and "job" in data
    ):
        data = data["job"]

    # {"resources": {"jobs": {...}}}
    if (
        isinstance(data, dict)
        and "resources" in data
    ):

        resources = data["resources"]

        if (
            isinstance(resources, dict)
            and "jobs" in resources
        ):

            jobs = resources["jobs"]

            if isinstance(jobs, dict):

                if len(jobs) == 1:
                    data = list(
                        jobs.values()
                    )[0]

    if not isinstance(data, dict):
        raise ValueError(
            "Job definition must be a dictionary."
        )

    print("========== JOB DEFINITION ==========")
    print(data)
    return data

# ============================================================
# PERMISSION DEPLOYMENT
# ============================================================

def deploy_permissions(
    definition,
    dry_run=True
):

    print_section(
        "PERMISSION DEPLOYMENT"
    )

    permissions = definition.get(
        "permissions",
        []
    )
    if not permissions:
        print("No Unity Catalog permissions found."
              "Skipping permission deployment."
        )
        return {
            "status" : "SKIPPED"
        }

    for permission in permissions:

        object_type = (
            permission.get(
                "object_type"
            )
        )

        object_name = (
            permission.get(
                "object_name"
            )
        )

        principal = (
            permission.get(
                "principal"
            )
        )

        privilege = (
            permission.get(
                "privilege"
            )
        )

        if object_type == "catalog":

            sql = (
                f"GRANT {privilege} "
                f"ON CATALOG {object_name} "
                f"TO `{principal}`"
            )

        elif object_type == "schema":

            sql = (
                f"GRANT {privilege} "
                f"ON SCHEMA {object_name} "
                f"TO `{principal}`"
            )

        elif object_type == "table":

            sql = (
                f"GRANT {privilege} "
                f"ON TABLE {object_name} "
                f"TO `{principal}`"
            )

        else:

            print(
                f"Unsupported object type: "
                f"{object_type}"
            )

            continue

        print(sql)

        if not dry_run:

            spark.sql(sql)

    return {

        "status": "COMPLETED"

    }

# ============================================================
# 12. JOB DEPLOYMENT
# ============================================================

def deploy_job(
    w,
    job_definition,
    dry_run=True
):

    print_section("JOB DEPLOYMENT")

    definition = normalize_job_definition(
        job_definition
    )

    job_name = definition.get(
        "name",
        "MANHATTAN_MIGRATION_JOB"
    )

    print(f"Job name: {job_name}")

    if dry_run:

        print(
            "DRY RUN -> Job deployment skipped."
        )

        return {
            "status": "DRY_RUN",
            "job_id": None,
            "job_name": job_name
        }

    existing_job = None

    try:

        for job in w.jobs.list(
            name=job_name
        ):

            if (
                job.settings
                and job.settings.name == job_name
            ):
                existing_job = job
                break

    except Exception as e:

        print(
            f"Job lookup warning: {e}"
        )

    if existing_job:

        job_id = existing_job.job_id

        print(
            f"Existing job found: {job_id}"
        )

        job_settings = dict(definition)

        job_settings.pop(
            "job_id",
            None
        )

        job_settings.pop(
            "created_time",
            None
        )

        job_settings.pop(
            "creator_user_name",
            None
        )

        w.jobs.reset(
            job_id=job_id,
            new_settings=job_settings
        )

        print(
            f"✓ Job updated: {job_id}"
        )

        return {
            "status": "UPDATED",
            "job_id": str(job_id),
            "job_name": job_name
        }
    WORKSPACE_ROOT = "/Workspace/Shared/migration"

    for task in definition.get("tasks", []):

        spark_task = task.get(
            "spark_python_task"
        )

        if not spark_task:
            continue

        file_name = spark_task.get(
            "python_file"
        )

        if not file_name:
            continue

        if "bronze_loader.py" in file_name:

            spark_task["python_file"] = (
                f"{WORKSPACE_ROOT}/bronze_loader.py"
            )

        elif "silver_transform.py" in file_name:

            spark_task["python_file"] = (
                f"{WORKSPACE_ROOT}/silver_transform.py"
            )

        elif "gold_transform.py" in file_name:

            spark_task["python_file"] = (
                f"{WORKSPACE_ROOT}/gold_transform.py"
            )

    print(
        json.dumps(
            definition,
            indent=2
        )
    )
    
    definition["environments"] = [

        {
            "environment_key": "default",
            "spec": {
                "client": "1"
            }
        }
    ]

    for task in definition.get("tasks", []):

        task["environment_key"] = "default"

    response = w.api_client.do(
        method="POST",
        path="/api/2.1/jobs/create",
        body=definition
    )

    job_id = response.get("job_id")

    print(
        f"✓ Job created: {job_id}"
    )

    return {
        "status": "CREATED",
        "job_id": str(job_id),
        "job_name": job_name
    }


# ============================================================
# 13. PIPELINE DEFINITION NORMALIZATION
# ============================================================

def normalize_pipeline_definition(data):

    if data is None:
        raise ValueError(
            "Empty pipeline definition."
        )

    # {"pipeline": {...}}
    if (
        isinstance(data, dict)
        and "pipeline" in data
    ):
        data = data["pipeline"]

    # {"resources": {"pipelines": {...}}}
    if (
        isinstance(data, dict)
        and "resources" in data
    ):

        resources = data["resources"]

        if (
            isinstance(resources, dict)
            and "pipelines" in resources
        ):

            pipelines = resources["pipelines"]

            if (
                isinstance(pipelines, dict)
                and len(pipelines) == 1
            ):

                data = list(
                    pipelines.values()
                )[0]

    if not isinstance(data, dict):
        raise ValueError(
            "Pipeline definition must "
            "be a dictionary."
        )
    print("========== PIPELINE DEFINITION ==========")
    print(data)
    return data


# ============================================================
# 14. PIPELINE DEPLOYMENT
# ============================================================


def deploy_pipeline(
    w,
    pipeline_definition,
    dry_run=True
):

    print_section("PIPELINE DEPLOYMENT")

    definition = normalize_pipeline_definition(
        pipeline_definition
    )

    pipeline_name = definition.get(
        "name",
        "MANHATTAN_MIGRATION_PIPELINE"
    )

    print(
        f"Pipeline name: {pipeline_name}"
    )

    if dry_run:

        print(
            "DRY RUN -> Pipeline deployment skipped."
        )

        return {
            "status": "DRY_RUN",
            "pipeline_id": None,
            "pipeline_name": pipeline_name
        }

    existing_pipeline = None

    try:

        for pipeline in w.pipelines.list_pipelines():

            if pipeline.name == pipeline_name:

                existing_pipeline = pipeline
                break

    except Exception as e:

        print(
            f"Pipeline lookup warning: {e}"
        )
# ======================================================
# PATH REWRITE MOVED HERE
# ======================================================
    WORKSPACE_ROOT = "/Workspace/Shared/migration"

    for library in definition.get(
        "libraries",
        []
    ):
        file_ref = library.get("file")
        if not file_ref:
            continue
        path = file_ref.get("path")

        if not path:
            continue
        if "bronze_loader.py" in path:
            file_ref["path"] = (
                f"{WORKSPACE_ROOT}/bronze_loader.py"
            )
        elif "silver_transform.py" in path:
            file_ref["path"] = (
                f"{WORKSPACE_ROOT}/silver_transform.py"
            )
        elif "gold_transform.py" in path:
            file_ref["path"] = (
                f"{WORKSPACE_ROOT}/gold_transform.py"
            )
# ===========================
# UPDATE BLOCK
# ===========================

    if existing_pipeline:

        pipeline_id = existing_pipeline.pipeline_id

        print(
            f"Existing pipeline found: "
            f"{pipeline_id}"
        )

        update_definition = dict(
            definition
        )

        update_definition.pop(
            "id",
            None
        )

        update_definition.pop(
            "pipeline_id",
            None
        )

        response = w.api_client.do(
            method="PUT",
            path=f"/api/2.0/pipelines/{pipeline_id}",
            body=update_definition
        )

        print(
            f"✓ Pipeline updated: "
            f"{pipeline_id}"
        )

        return {
            "status": "UPDATED",
            "pipeline_id": str(pipeline_id),
            "pipeline_name": pipeline_name
        }

    print(
        json.dumps(
            definition,
            indent=2
        )
    )

    response = w.api_client.do(
        method="POST",
        path="/api/2.0/pipelines",
        body=definition
    )

    pipeline_id = response.get("pipeline_id")

    print(
        f"✓ Pipeline created: {pipeline_id}"
    )

    return {
        "status": "CREATED",
        "pipeline_id": str(pipeline_id),
        "pipeline_name": pipeline_name
    }



# ============================================================
# 15. OPTIONAL JOB EXECUTION
# ============================================================

def run_deployed_job(
    w,
    job_id,
    dry_run=True
):

    print_section("JOB EXECUTION")

    if not job_id:
        print("No job ID available.")
        return None

    if dry_run:

        print(
            f"DRY RUN -> Would run job {job_id}"
        )

        return None

    response = w.jobs.run_now(
        job_id=int(job_id)
    )

    run_id = response.run_id

    print(
        "✓ Job execution started"
    )

    print(
        f"Run ID: {run_id}"
    )

    return str(run_id)


# ============================================================
# 16. MAIN DEPLOYMENT AGENT
# ============================================================

deployment_id = (
    "DEPLOY_"
    + utc_now().strftime("%Y%m%d%H%M%S")
    + "_"
    + uuid.uuid4().hex[:6]
)

started_at = utc_now()

selected_artifact = ARTIFACT_NAME
package_path = None

deployment_results = []


print_section(
    f"015 DEPLOYMENT AGENT STARTED: "
    f"{deployment_id}"
)

try:

    # --------------------------------------------------------
    # STEP 1: DISCOVER PACKAGE
    # --------------------------------------------------------

    packages = discover_packages()

    package = select_package(
        packages,
        ARTIFACT_NAME or None
    )

    selected_artifact = package["name"]
    package_path = package["path"]

    print(
        f"\nSelected artifact:"
        f"\n{selected_artifact}"
    )

    print(
        f"Package path:"
        f"\n{package_path}"
    )

    # --------------------------------------------------------
    # STEP 2: INSPECT PACKAGE
    # --------------------------------------------------------

    print_section(
        "PACKAGE CONTENT INSPECTION"
    )

    files = inspect_package(
        package_path
    )

    # --------------------------------------------------------
    # STEP 3: VALIDATE PACKAGE
    # --------------------------------------------------------

    validate_package(files)

    (
        catalog_files,
        schema_files,
        table_files
    ) = discover_database_artifacts(
        files
    )
    print(
    f"Catalog Files : {len(catalog_files)}"
    )

    print(
        f"Schema Files : {len(schema_files)}"
    )

    print(
        f"Table Files : {len(table_files)}"
    )

    if not catalog_files:

        print(
            "WARNING: No catalog file found"
        )

    if not schema_files:

        print(
            "WARNING: No schema files found"
        )

    if not table_files:

        print(
            "WARNING: No table files found"
        )

    # --------------------------------------------------------
    # STEP 4: DISCOVER DEPLOYMENT DEFINITIONS
    # --------------------------------------------------------

    (
        job_candidates,
        pipeline_candidates,
        permission_candidates
    ) = discover_deployment_definitions(
        files
    )

    # --------------------------------------------------------
    # STEP 5: INITIALIZE SDK
    # --------------------------------------------------------

    w = initialize_workspace_client()

    # --------------------------------------------------------
    # STEP 6A: CATALOG DEPLOYMENT
    # --------------------------------------------------------
    try:
        deploy_catalogs(
            catalog_files,
            DRY_RUN
        )
        deployment_results.append({
            "type": "CATALOG"
        })

        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "CATALOG_DEPLOYMENT",
            "COMPLETED",
            started_at,
            utc_now(),
            package_path
        )
    except Exception as e:
        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "CATALOG_DEPLOYMENT",
            "FAILED",
            started_at,
            utc_now(),
            package_path,
            str(e)
        )
        raise       

# --------------------------------------------------------
# STEP 6B: SCHEMA DEPLOYMENT
# --------------------------------------------------------
    try:

        deploy_schemas(
            schema_files,
            DRY_RUN
        )
        deployment_results.append({
            "type" : "SCHEMA"
        })

        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "SCHEMA_DEPLOYMENT",
            "COMPLETED",
            started_at,
            utc_now(),
            package_path
        )
    except Exception as e:
        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "SCHEMA_DEPLOYMENT",
            "FAILED",
            started_at,
            utc_now(),
            package_path,
            str(e)
        )
        raise


# --------------------------------------------------------
# STEP 6C: TABLE DEPLOYMENT
# --------------------------------------------------------
    try:

        deploy_tables(
            table_files,
            DRY_RUN
        )
        deployment_results.append({
            "type": "TABLE"
        })

        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "TABLE_DEPLOYMENT",
            "COMPLETED",
            started_at,
            utc_now(),
            package_path
        )
    except Exception as e:
        write_audit(
            deployment_id,
            selected_artifact,
            ENVIRONMENT,
            "TABLE_DEPLOYMENT",
            "FAILED",
            started_at,
            utc_now(),
            package_path,
            str(e)
        )
        raise

    # --------------------------------------------------------
# STEP 6D: PERMISSION DEPLOYMENT
# --------------------------------------------------------

    for permission_file in permission_candidates:

        try:

            definition = parse_definition(
                permission_file["path"]
            )

            result = deploy_permissions(
                definition,
                DRY_RUN
            )
            deployment_results.append({
                "type": "PERMISSION"
            })

            write_audit(
                deployment_id,
                selected_artifact,
                ENVIRONMENT,
                "PERMISSION_DEPLOYMENT",
                result["status"],
                started_at,
                utc_now(),
                package_path
            )
        except Exception as e:
            write_audit(
                deployment_id,
                selected_artifact,
                ENVIRONMENT,
                "PERMISSION_DEPLOYMENT",
                "FAILED",
                started_at,
                utc_now(),
                package_path,
                str(e)
            )
            raise

    # --------------------------------------------------------
    # STEP 7: PIPELINE DEPLOYMENT
    # --------------------------------------------------------

    for pipeline_file in pipeline_candidates:

        print(
            f"\nProcessing pipeline definition:"
            f"\n{pipeline_file['path']}"
        )

        try:

            definition = parse_definition(
                pipeline_file["path"]
            )

            result = deploy_pipeline(
                w,
                definition,
                DRY_RUN
            )

            deployment_results.append({
                "type": "PIPELINE",
                "path": pipeline_file["path"],
                "result": result
            })

            write_audit(
                deployment_id=deployment_id,
                artifact_name=selected_artifact,
                environment=ENVIRONMENT,
                action="PIPELINE_DEPLOYMENT",
                status=result["status"],
                started_at=started_at,
                completed_at=utc_now(),
                package_path=package_path
            )

        except Exception as e:

            error_message = (
                f"{type(e).__name__}: {str(e)}"
            )

            print(
                f"PIPELINE DEPLOYMENT FAILED:"
                f"\n{error_message}"
            )

            write_audit(
                deployment_id=deployment_id,
                artifact_name=selected_artifact,
                environment=ENVIRONMENT,
                action="PIPELINE_DEPLOYMENT",
                status="FAILED",
                started_at=started_at,
                completed_at=utc_now(),
                package_path=package_path,
                error_message=error_message
            )
            raise

# --------------------------------------------------------
# STEP 8: JOB DEPLOYMENT
# --------------------------------------------------------

    for job_file in job_candidates:

        print(
            f"\nProcessing job definition:"
            f"\n{job_file['path']}"
        )

        try:

            definition = parse_definition(
                job_file["path"]
            )

            result = deploy_job(
                w,
                definition,
                DRY_RUN
            )

            deployment_results.append({
                "type": "JOB",
                "path": job_file["path"],
                "result": result
            })

            write_audit(
                deployment_id=deployment_id,
                artifact_name=selected_artifact,
                environment=ENVIRONMENT,
                action="JOB_DEPLOYMENT",
                status=result["status"],
                started_at=started_at,
                completed_at=utc_now(),
                package_path=package_path
            )

            # Optional execution
            if (
                RUN_AFTER_DEPLOY
                and result.get("job_id")
            ):

                run_id = run_deployed_job(
                    w,
                    result["job_id"],
                    DRY_RUN
                )

                write_audit(
                    deployment_id=deployment_id,
                    artifact_name=selected_artifact,
                    environment=ENVIRONMENT,
                    action="JOB_RUN",
                    status=(
                        "STARTED"
                        if run_id
                        else "DRY_RUN"
                    ),
                    started_at=started_at,
                    completed_at=utc_now(),
                    package_path=package_path,
                    job_run_id=run_id
                )

        except Exception as e:

            error_message = (
                f"{type(e).__name__}: {str(e)}"
            )

            print(
                f"JOB DEPLOYMENT FAILED:"
                f"\n{error_message}"
            )

            write_audit(
                deployment_id=deployment_id,
                artifact_name=selected_artifact,
                environment=ENVIRONMENT,
                action="JOB_DEPLOYMENT",
                status="FAILED",
                started_at=started_at,
                completed_at=utc_now(),
                package_path=package_path,
                error_message=error_message
            )
            raise

    # --------------------------------------------------------
    # STEP 9: FINAL AUDIT
    # --------------------------------------------------------

    completed_at = utc_now()

    final_status = (
        "DRY_RUN_COMPLETED"
        if DRY_RUN
        else "COMPLETED"
    )

    write_audit(
        deployment_id=deployment_id,
        artifact_name=selected_artifact,
        environment=ENVIRONMENT,
        action="DEPLOYMENT_COMPLETED",
        status=final_status,
        started_at=started_at,
        completed_at=completed_at,
        package_path=package_path
    )

    # --------------------------------------------------------
    # SUMMARY
    # --------------------------------------------------------

    print_section(
        "015 DEPLOYMENT AGENT COMPLETED"
    )

    print(
        f"Deployment ID : {deployment_id}"
    )

    print(
        f"Artifact      : {selected_artifact}"
    )

    print(
        f"Environment   : {ENVIRONMENT}"
    )

    print(
        f"Dry Run       : {DRY_RUN}"
    )

    print(
        f"Deployment Objects : "
        f"{len(deployment_results)}"
    )

    for item in deployment_results:

        print(
            f" - {item['type']}"
        )

    print(
        f"Audit Table   : {AUDIT_TABLE}"
    )

    print(
        "\n✓ Deployment Agent completed."
    )

except Exception as e:

    completed_at = utc_now()

    error_message = (
        f"{type(e).__name__}: {str(e)}"
    )

    print_section(
        "015 DEPLOYMENT AGENT FAILED"
    )

    print(error_message)

    print("\nTRACEBACK:")
    print(traceback.format_exc())

    try:

        write_audit(
            deployment_id=deployment_id,
            artifact_name=selected_artifact,
            environment=ENVIRONMENT,
            action="DEPLOYMENT",
            status="FAILED",
            started_at=started_at,
            completed_at=completed_at,
            package_path=package_path,
            error_message=error_message
        )

    except Exception as audit_error:

        print(
            f"Audit failure: {audit_error}"
        )

    raise


# ============================================================
# 10. AUDIT CHECK
# ============================================================

display(
    spark.sql(f"""
        SELECT
            deployment_id,
            artifact_name,
            environment,
            action,
            deployment_status,
            job_run_id,
            started_at,
            completed_at,
            error_message,
            package_path
        FROM {AUDIT_TABLE}
        ORDER BY started_at DESC
        LIMIT 20
    """)
)
